const API_URL='https://script.google.com/macros/s/AKfycbxIH2VtgwRi50xduXgrkYrjD0yrzNfQ5vCWt1XgOzil6LZSgXNj6MJo9jPYvOkjNHdu/exec';
const $=id=>document.getElementById(id);
const TARGET_GRADES=['小４','小５','小６','中１','中２','中３'];
let students=[],selected=new Map(),activeGrades=new Set(TARGET_GRADES);
const INITIAL_EXAM_NUMBERS={"1001":"5001","1058":"2004","1097":"1004","1100":"1005","1117":"1006","1139":"1001","1154":"1002","1156":"6001","1158":"4001","1164":"1007","1169":"2002","1173":"6002","1176":"5002","1180":"5003","1181":"1015","1187":"4002","1188":"1008","1189":"5004","1191":"1003","1196":"6003","1197":"5005","1198":"4003","1202":"3011","1204":"4004","1214":"3013","1217":"5006","1219":"3018","1223":"5007","1226":"2007","1227":"3014","1237":"3020","1239":"1013","1248":"2033","1249":"2008","1252":"2009","1253":"2010","1256":"6004","1257":"3016","1259":"3021","1261":"5008","1263":"2013","1264":"2014","1269":"2015","1273":"6005","1276":"3025","1278":"6006","1280":"5009","1282":"2017","1285":"6007","1286":"3030","1287":"3031","1289":"2016","1290":"3026","1292":"5010","1293":"2018","1294":"2022","1295":"3027","1296":"2019","1297":"1014","1298":"2020","1299":"2023","1300":"5011","1301":"5012","1302":"2024","1303":"2025","1304":"2021","1305":"3028","1306":"2026","1307":"2027","1308":"6008","1311":"1015","1312":"3029","1313":"1009","1315":"6009","1316":"2028","1318":"2034","1319":"2035","1320":"2036","1321":"1010","1322":"1011","1324":"2029","1325":"3032","1326":"2030","1327":"3033","1328":"2031","1329":"2032","1330":"1012"};
const DYNAMIC_NUMBER_KEY='step_exam_dynamic_numbers_v2';
const GRADE_ORDER=['小１','小２','小３','小４','小５','小６','中１','中２','中３','高１'];

function escapeHtml(value){return String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));}
function normalize(value){return String(value??'').normalize('NFKC').toLowerCase().replace(/[\s　]+/g,'').replace(/[ァ-ヶ]/g,c=>String.fromCharCode(c.charCodeAt(0)-0x60));}
function jsonp(action,params={}){return new Promise((resolve,reject)=>{const cb=`exam_cb_${Date.now()}_${Math.random().toString(36).slice(2)}`;const script=document.createElement('script');const timer=setTimeout(()=>finish(new Error('通信がタイムアウトしました。')),45000);function cleanup(){clearTimeout(timer);delete window[cb];script.remove();}function finish(error,data){cleanup();error?reject(error):resolve(data);}window[cb]=data=>data?.error?finish(new Error(data.message||'読み込みに失敗しました。')):finish(null,data);script.onerror=()=>finish(new Error('生徒情報を読み込めませんでした。'));script.src=`${API_URL}?${new URLSearchParams({action,callback:cb,...params})}`;document.body.appendChild(script);});}
async function postJson(payload){const controller=new AbortController();const timer=setTimeout(()=>controller.abort(),60000);try{const response=await fetch(API_URL,{method:'POST',body:JSON.stringify(payload),signal:controller.signal});if(!response.ok)throw new Error('更新に失敗しました。');const data=await response.json();if(data?.error)throw new Error(data.message||'更新に失敗しました。');return data;}finally{clearTimeout(timer);}}
function setStatus(message,type=''){const el=$('status');el.textContent=message;el.className=`status ${type}`.trim();}
function currentAcademicYear_(){const now=new Date();return now.getMonth()>=3?now.getFullYear():now.getFullYear()-1;}
function selectedYear_(){return Number($('yearSelect').value)||currentAcademicYear_();}
function yearAvailable_(year,now=new Date()){return now>=new Date(year,2,1);}
function setupYearOptions_(){const current=currentAcademicYear_(),next=current+1,available=yearAvailable_(next);$('yearSelect').innerHTML=`<option value="${current}">${current}年度</option><option value="${next}" ${available?'':'disabled'}>${next}年度${available?'':'（3月1日から選択可）'}</option>`;const notice=$('yearNotice');notice.hidden=available;notice.textContent=`※${next}年度は${next}年3月1日から選択できます。それ以前は選択できません。`;}
function advanceGrade_(grade,steps){const index=GRADE_ORDER.indexOf(grade);if(index<0)return'';return GRADE_ORDER[index+steps]||'';}
function filtered(){const campus=$('campusFilter').value,q=normalize($('searchInput').value);return students.filter(s=>(campus==='all'||s.campus===campus)&&activeGrades.has(s.grade)&&(!q||[s.studentId,s.name,s.kana].map(normalize).some(v=>v.includes(q)))).sort((a,b)=>Number(a.examNumber)-Number(b.examNumber));}
function renderGradeButtons(){$('gradeButtons').innerHTML=TARGET_GRADES.map(g=>`<button type="button" class="gradeBtn ${activeGrades.has(g)?'active':''}" data-grade="${g}">${g}</button>`).join('');document.querySelectorAll('.gradeBtn').forEach(btn=>btn.onclick=()=>{activeGrades.has(btn.dataset.grade)?activeGrades.delete(btn.dataset.grade):activeGrades.add(btn.dataset.grade);renderGradeButtons();renderStudents();});}
function renderStudents(){const list=filtered();$('listCount').textContent=`${list.length}人表示 / ${students.length}人在籍`;$('studentList').innerHTML=list.map(s=>`<label class="studentRow ${selected.has(s.studentId)?'selected':''}" data-id="${escapeHtml(s.studentId)}"><input type="checkbox" ${selected.has(s.studentId)?'checked':''}><span class="examNo">${escapeHtml(s.examNumber)}</span><strong>${escapeHtml(s.name)}</strong><span class="gradeBadge">${escapeHtml(s.grade)}</span><span class="campus">${escapeHtml(s.campus)}校</span><span class="campus">ID ${escapeHtml(s.studentId)}</span></label>`).join('')||'<div class="muted" style="padding:18px">該当する生徒はいません。</div>';document.querySelectorAll('.studentRow').forEach(row=>row.onclick=e=>{e.preventDefault();toggleStudent(row.dataset.id);});renderSelected();}
function toggleStudent(id){const s=students.find(x=>x.studentId===id);if(!s)return;selected.has(id)?selected.delete(id):selected.set(id,s);renderStudents();}
function renderSelected(){const list=[...selected.values()].sort((a,b)=>Number(a.examNumber)-Number(b.examNumber));$('selectedCount').textContent=`${list.length}人`;$('selectedList').innerHTML=list.length?list.map(s=>`<span class="selectedChip"><b>${escapeHtml(s.examNumber)}</b> ${escapeHtml(s.name)}<button type="button" data-remove="${escapeHtml(s.studentId)}" aria-label="${escapeHtml(s.name)}を解除">×</button></span>`).join(''):'<span class="muted">まだ選択されていません。</span>';$('selectedList').querySelectorAll('[data-remove]').forEach(btn=>btn.onclick=()=>{selected.delete(btn.dataset.remove);renderStudents();});$('printBtn').disabled=!list.length;renderPreview();}
function campusName(s){return s?.campus==='大手'?'大手町校':s?.campus==='神領'?'神領校':String(s?.campus||'');}
const TICKET_ILLUSTRATION_SRC='data:image/webp;base64,';
const EXAM_SCHEDULES={
  elementary:{label:'小学生',rows:[['12:50～13:00','受験票記入'],['13:00～13:30','算数（30分）'],['13:35～14:05','国語（30分）'],['14:10～14:40','理科（30分）'],['14:45～15:15','社会（30分）'],['※15:20～15:50','英語（30分）']]},
  junior12:{label:'中1・中2',rows:[['12:50～13:00','受験票記入'],['13:00～13:40','数学（40分）'],['13:45～14:25','英語（40分）'],['14:30～15:10','国語（40分）'],['15:15～15:50','理科（35分）'],['15:55～16:30','社会（35分）']]},
  junior3:{label:'中3',rows:[['12:50～13:00','受験票記入'],['13:00～13:45','数学（45分）'],['13:50～14:35','国語（45分）'],['14:40～15:30','英語（50分）'],['15:35～16:20','理科（45分）'],['16:25～17:10','社会（45分）']]}
};
function scheduleForGrade_(grade){if(['小４','小５','小６'].includes(grade))return EXAM_SCHEDULES.elementary;if(['中１','中２'].includes(grade))return EXAM_SCHEDULES.junior12;if(grade==='中３')return EXAM_SCHEDULES.junior3;return null;}
function scheduleMarkup_(grade){const schedule=scheduleForGrade_(grade);if(!schedule)return'';return `<section class="examSchedule"><div class="scheduleHeader"><h3>試験時間割（${escapeHtml(schedule.label)}）</h3><img class="ticketIllustration" src="${TICKET_ILLUSTRATION_SRC}" alt=""></div><table><tbody>${schedule.rows.map(([time,subject])=>`<tr><th>${escapeHtml(time)}</th><td>${escapeHtml(subject)}</td></tr>`).join('')}</tbody></table></section>`;}
function ticketMarkup(s,print=false){const round=$('roundSelect').value,year=selectedYear_();const footer=`個別指導ステップ ${campusName(s)}`.trim();return `<div class="${print?'printPage':''}"><div class="ticketTitle">第${escapeHtml(round)}回 愛知全県模試受験票</div><div class="ticketTable"><div class="ticketLabel">塾名</div><div class="ticketValue">個別指導ステップ</div><div class="ticketLabel">塾コード</div><div class="ticketValue number">4258</div><div class="ticketLabel">生徒コード</div><div class="ticketValue number">${escapeHtml(s?.examNumber||'----')}</div><div class="ticketLabel">氏名</div><div class="ticketValue">${escapeHtml(s?.name||'選択した生徒の氏名')}</div><div class="ticketLabel">学区</div><div class="ticketValue">尾張</div></div>${scheduleMarkup_(s?.grade)}<div class="ticketFooter"><span>${year}年度</span><span>${escapeHtml(footer)}</span></div></div>`;}
function renderPreview(){const first=[...selected.values()].sort((a,b)=>Number(a.examNumber)-Number(b.examNumber))[0];$('ticketPreview').innerHTML=ticketMarkup(first,false)+(first?'':`<p class="previewHint">生徒を選択すると氏名と受験番号が入ります。</p>`);}
function fallbackStudent_(s){const id=String(s.id||'');const grade=String(s.grade||'').replace('小1','小１').replace('小2','小２').replace('小3','小３').replace('小4','小４').replace('小5','小５').replace('小6','小６').replace('中1','中１').replace('中2','中２').replace('中3','中３');const school=String(s.school||'');return {studentId:id,name:String(s.name||''),kana:String(s.kana||s.furigana||''),baseGrade:grade,grade,campus:school.includes('神領')?'神領':school.includes('大手')?'大手':school,examNumber:INITIAL_EXAM_NUMBERS[id]};}
function numberFitsGrade_(number,grade){const n=Number(number),start={'中１':1000,'中２':2000,'中３':3000,'小４':4000,'小５':5000,'小６':6000}[grade];return Boolean(start&&n>start&&n<start+1000);}
function examNumberWarnings_(list){const owners=new Map(),warnings=[];(list||[]).forEach(s=>{const number=String(s.examNumber||'').trim();if(!number)return;const previous=owners.get(number);if(previous)warnings.push(`受験番号${number}が重複しています（${previous}・${s.name}）`);else owners.set(number,s.name);});return [...new Set(warnings)];}
function fallbackStudents_(base,year){let dynamic={};try{dynamic=JSON.parse(localStorage.getItem(DYNAMIC_NUMBER_KEY)||'{}')||{};}catch(e){}const yearKey=String(year),yearSaved=dynamic[yearKey]||{},steps=year-currentAcademicYear_();const all=(Array.isArray(base)?base:[]).map(fallbackStudent_);const initial=year===2026?INITIAL_EXAM_NUMBERS:{};const highestRegistered=Math.max(0,...Object.keys(INITIAL_EXAM_NUMBERS).map(Number));const eligible=all.map(s=>{const saved=yearSaved[s.studentId];s.grade=saved?.grade||advanceGrade_(s.baseGrade,steps);return s;}).filter(s=>TARGET_GRADES.includes(s.grade)&&(year!==2026||initial[s.studentId]||yearSaved[s.studentId]||Number(s.studentId)>highestRegistered)).sort((a,b)=>Number(a.studentId)-Number(b.studentId));const max={'中１':1000,'中２':2000,'中３':3000,'小４':4000,'小５':5000,'小６':6000};Object.entries(initial).forEach(([id,n])=>{const item=eligible.find(s=>s.studentId===id);if(item&&numberFitsGrade_(n,item.grade))max[item.grade]=Math.max(max[item.grade],Number(n));});Object.values(yearSaved).forEach(x=>{if(x&&numberFitsGrade_(x.number,x.grade))max[x.grade]=Math.max(max[x.grade],Number(x.number));});eligible.forEach(s=>{const first=initial[s.studentId],saved=yearSaved[s.studentId];if(numberFitsGrade_(first,s.grade))s.examNumber=first;else if(saved&&numberFitsGrade_(saved.number,s.grade))s.examNumber=String(saved.number);else{s.examNumber=String(++max[s.grade]);yearSaved[s.studentId]={grade:s.grade,number:s.examNumber};}s.year=year;});dynamic[yearKey]=yearSaved;localStorage.setItem(DYNAMIC_NUMBER_KEY,JSON.stringify(dynamic));return eligible;}
async function loadStudents(refresh=false){const year=selectedYear_();setStatus(`☆マスタから${year}年度の生徒情報と受験番号を更新しています…`);try{let data=await jsonp('getExamTicketStudents',{year,refresh:refresh?'1':'0',_:Date.now()});let fallback=false;if(!Array.isArray(data?.students)){await postJson({action:'refreshStudents'});const base=await jsonp('getStudents',{_:Date.now()});const fallbackList=fallbackStudents_(base,year);data={year,students:fallbackList,warnings:examNumberWarnings_(fallbackList)};fallback=true;}students=data.students;const valid=new Set(students.map(s=>s.studentId));for(const id of selected.keys())if(!valid.has(id))selected.delete(id);renderStudents();const warning=(data.warnings||[]).join(' / ');setStatus(`${year}年度：${students.length}名を読み込みました。新規番号は学年別の最大番号より後ろに割り当てます。${fallback?'（更新済み生徒情報を使用）':''}${warning?'　注意：'+warning:''}`,warning?'error':'ok');}catch(e){setStatus(e.name==='AbortError'?'更新に時間がかかっています。もう一度「生徒情報を更新」を押してください。':e.message,'error');}}
function printTickets(){if(!selected.size)return;const list=[...selected.values()].sort((a,b)=>Number(a.examNumber)-Number(b.examNumber));$('printArea').innerHTML=list.map(s=>ticketMarkup(s,true)).join('');window.print();}

$('campusFilter').onchange=renderStudents;$('searchInput').oninput=renderStudents;$('roundSelect').onchange=renderPreview;$('yearSelect').onchange=()=>{selected.clear();loadStudents(false);};$('selectVisibleBtn').onclick=()=>{filtered().forEach(s=>selected.set(s.studentId,s));renderStudents();};$('clearBtn').onclick=()=>{selected.clear();renderStudents();};$('refreshBtn').onclick=()=>loadStudents(true);$('printBtn').onclick=printTickets;window.addEventListener('afterprint',()=>{$('printArea').innerHTML='';});setupYearOptions_();renderGradeButtons();renderPreview();loadStudents();
